import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { readFile, writeFile, mkdtemp, rm } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const run = promisify(execFile);
const hash = value => createHash('sha256').update(value).digest('hex');
const normalize = value => value.normalize('NFKC').replace(/[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed\u200e\u200f]/gu,'').replace(/[.,،]/gu,'').replace(/\s+/gu,' ').trim();
const freeze = JSON.parse(await readFile('/holdouts/freeze.json','utf8'));
const gold = JSON.parse(await readFile('/holdouts/gold-manifest.json','utf8'));
const original = JSON.parse(await readFile('/fixtures/manifest.json','utf8'));
const fixtures = gold.cases.map(c => ({...c,path:`/holdouts/${c.filename}`,sha:freeze.files[c.filename].sha256})).concat([{id:'english-existing-control',path:'/fixtures/scanned-en.pdf',sha:original.files['scanned-en.pdf'],lines:original.recognition_oracle.en}]);
const directory = await mkdtemp('/tmp/ocr-diagnostic-');
const invoke = (name,args) => run(name,args,{timeout:30000,killSignal:'SIGKILL',maxBuffer:4*1024*1024,env:{PATH:'/usr/bin:/bin',LANG:'C.UTF-8',OMP_THREAD_LIMIT:'1'}});
const parse = tsv => {
 const lines = new Map(); let total=0,chars=0;
 for(const row of tsv.split(/\r?\n/).slice(1)) {
  const c=row.split('\t'); const word=c.slice(11).join('\t').trim();const conf=Number(c[10]);
  if(c[0]!=='5'||c.length<12||!word||!Number.isFinite(conf)||conf<0||conf>100)continue;
  const key=c.slice(1,5).join(':');const words=lines.get(key)||[];words.push(word);lines.set(key,words);total+=conf*word.length;chars+=word.length;
 }
 return {text:[...lines.values()].map(x=>x.join(' ')).join('\n'),confidence:chars?Math.round(total/chars):0};
};
const cases=[];
try {
 for(const fixture of fixtures) {
  const bytes = await readFile(fixture.path);
  if(hash(bytes)!==fixture.sha)throw Error('Frozen PDF changed');
  for(const config of [{scale:2000,lang:'ara+eng',psm:3},{scale:1000,lang:'ara',psm:6}]) {
   const {scale,lang,psm}=config;
   const prefix=`${directory}/${fixture.id}-${scale}`;
   await invoke('pdftoppm',['-f','1','-l','1','-scale-to',String(scale),'-png','-singlefile',fixture.path,prefix]);
   const image=await readFile(`${prefix}.png`), start=performance.now();
   const output=await invoke('tesseract',[`${prefix}.png`,'stdout','-l',lang,'--psm',String(psm),'-c','tessedit_create_tsv=1']);
   const value=parse(output.stdout),norm=normalize(value.text);
   let previous=-1;
   const matches=fixture.lines.map(expected=>{const position=norm.indexOf(normalize(expected));const found=position>previous;if(found)previous=position;return found;});
   const record={case:fixture.id,fixture_sha256:fixture.sha,...config,elapsed_ms:Math.round(performance.now()-start),image_sha256:hash(image),tsv_sha256:hash(output.stdout),...value,matches,critical_literals:fixture.critical_literals?.map(literal=>({literal,present:norm.includes(normalize(literal))})),exact_gold:matches.every(Boolean)};
   cases.push(record);await writeFile(`/outputs/${fixture.id}-${scale}-${lang}-${psm}.tsv`,output.stdout);
   console.log(JSON.stringify(record));
  }
 }
 const data={scope:'Frozen independent synthetic holdouts and unchanged English control; baseline versus single selected diagnostic candidate; no production change or automatic semantic qualification',holdout_freeze_sha256:hash(await readFile('/holdouts/freeze.json')),holdout_gold_sha256:hash(await readFile('/holdouts/gold-manifest.json')),engine:(await invoke('tesseract',['--version'])).stdout.split('\n')[0],cases};
 await writeFile('/outputs/matrix.json',JSON.stringify(data,null,2)+'\n');
} finally {await rm(directory,{recursive:true,force:true});}
